sql_query:
SELECT "Secondary endpoint"
FROM clinical_trials
WHERE "Included in MA" = 'Yes' AND "Name of ICI" = 'Ipilimumab' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Secondary endpoint" AS source_value FROM clinical_trials WHERE "Included in MA" = 'Yes' AND "Name of ICI" = 'Ipilimumab' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_endpoint_role(source_value, 'Secondary endpoint') AS "endpoint_role"
FROM base;
